"""Exact, randomness-free verification of the finite-dimensional theorems.

Nothing here is sampled: every number is obtained either by enumerating all
closed walks on K_N or by averaging exactly over all 2^{N(N-1)/2} sign matrices
in integer arithmetic.  The script checks, at small N:

  * the dichotomy   E[tr(W^m)] = #{even closed m-walks};
  * exact vanishing of every odd trace moment;
  * the closed forms  E[tr(W^2)] = N(N-1)  and  E[tr(W^4)] = 2N(N-1)^2 - N(N-1);
  * the spanning-tree bound: an even closed 2k-walk visits at most k+1 vertices;
  * the two-sided sandwich  (1-1/N)^k <= E[m_2k] <= (k+1)^{2k};
  * the deterministic identity tr(W^2) = N(N-1) for every single sign matrix.
"""

from __future__ import annotations

import itertools
from fractions import Fraction
from typing import Dict, List, Sequence, Tuple


def walk_edges(walk: Sequence[int]) -> Dict[Tuple[int, int], int] | None:
    mult: Dict[Tuple[int, int], int] = {}
    m = len(walk)
    for t in range(m):
        a, b = walk[t], walk[(t + 1) % m]
        if a == b:
            return None
        e = (a, b) if a < b else (b, a)
        mult[e] = mult.get(e, 0) + 1
    return mult


def even_walks(n: int, m: int) -> List[Tuple[int, ...]]:
    out: List[Tuple[int, ...]] = []
    for walk in itertools.product(range(n), repeat=m):
        mult = walk_edges(walk)
        if mult is not None and all(v % 2 == 0 for v in mult.values()):
            out.append(walk)
    return out


def sign_matrix(n: int, mask: int) -> List[List[int]]:
    edges = [(i, j) for i in range(n) for j in range(i + 1, n)]
    w = [[0] * n for _ in range(n)]
    for idx, (i, j) in enumerate(edges):
        s = 1 if (mask >> idx) & 1 else -1
        w[i][j] = s
        w[j][i] = s
    return w


def trace_power(a: List[List[int]], m: int) -> int:
    n = len(a)
    p = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    for _ in range(m):
        p = [[sum(p[i][k] * a[k][j] for k in range(n)) for j in range(n)] for i in range(n)]
    return sum(p[i][i] for i in range(n))


def exact_expectation(n: int, m: int) -> Fraction:
    e = n * (n - 1) // 2
    return Fraction(sum(trace_power(sign_matrix(n, mask), m) for mask in range(1 << e)), 1 << e)


def main() -> None:
    print("A. dichotomy: E[tr(W^m)] equals the number of even closed m-walks")
    print(f"   {'N':>3}{'m':>4}{'walks':>10}{'exact E[tr W^m]':>18}{'agree':>8}")
    for n in (2, 3, 4):
        for m in (2, 3, 4, 5):
            if n == 4 and m == 5:
                continue
            w = len(even_walks(n, m))
            e = exact_expectation(n, m)
            print(f"   {n:>3}{m:>4}{w:>10}{str(e):>18}{str(Fraction(w) == e):>8}")

    print("\nB. closed forms")
    print(f"   {'N':>3}{'N(N-1)':>10}{'E[tr W^2]':>12}{'2N(N-1)^2-N(N-1)':>20}{'E[tr W^4]':>12}")
    for n in (2, 3, 4):
        print(f"   {n:>3}{n*(n-1):>10}{str(exact_expectation(n, 2)):>12}"
              f"{2*n*(n-1)**2 - n*(n-1):>20}{str(exact_expectation(n, 4)):>12}")

    print("\nC. spanning-tree bound: an even closed 2k-walk visits at most k+1 vertices")
    print(f"   {'N':>3}{'2k':>5}{'max vertices seen':>20}{'bound k+1':>12}")
    for n in (3, 4, 5):
        for m in (2, 4, 6):
            walks = even_walks(n, m)
            mx = max((len(set(w)) for w in walks), default=0)
            print(f"   {n:>3}{m:>5}{mx:>20}{m//2 + 1:>12}")

    print("\nD. sandwich  (1-1/N)^k <= E[m_2k] <= (k+1)^{2k}   (exact walk counts)")
    print(f"   {'N':>3}{'k':>4}{'lower':>12}{'E[m_2k]':>14}{'upper':>12}{'ok':>5}")
    for n in (3, 4, 5):
        for k in (1, 2, 3):
            cnt = len(even_walks(n, 2 * k))
            val = Fraction(cnt, n ** (k + 1))
            lo = Fraction(n - 1, n) ** k
            hi = Fraction((k + 1) ** (2 * k))
            print(f"   {n:>3}{k:>4}{float(lo):>12.6f}{float(val):>14.6f}"
                  f"{float(hi):>12.1f}{str(lo <= val <= hi):>5}")

    print("\nE. determinism of tr(W^2): the same value for every sign matrix")
    for n in (3, 4):
        vals = {trace_power(sign_matrix(n, mask), 2) for mask in range(1 << (n * (n - 1) // 2))}
        print(f"   N = {n}: set of attained values = {vals}, N(N-1) = {n*(n-1)}")


if __name__ == "__main__":
    main()

