"""Exhaustive enumeration of even closed walks on the complete graph K_N.

For the symmetric +-1 ensemble, E[tr(W^m)] equals exactly the number of closed
m-walks that are loop-free and traverse every edge an even number of times.
This routine computes that integer by brute force.
"""

from __future__ import annotations

import itertools
from typing import Dict, Iterator, List, Sequence, Tuple


def edge_multiplicities(walk: Sequence[int]) -> Dict[Tuple[int, int], int] | None:
    """Multiset of edges traversed by the closed walk, or None if it has a loop."""
    mult: Dict[Tuple[int, int], int] = {}
    m = len(walk)
    for t in range(m):
        a, b = walk[t], walk[(t + 1) % m]
        if a == b:
            return None
        e = (a, b) if a < b else (b, a)
        mult[e] = mult.get(e, 0) + 1
    return mult


def is_even_closed_walk(walk: Sequence[int]) -> bool:
    """Loop-free with all edge multiplicities even."""
    mult = edge_multiplicities(walk)
    return mult is not None and all(v % 2 == 0 for v in mult.values())


def even_closed_walks(n_vertices: int, length: int) -> Iterator[Tuple[int, ...]]:
    """Yield every even closed walk of the given length on `n_vertices` vertices."""
    for walk in itertools.product(range(n_vertices), repeat=length):
        if is_even_closed_walk(walk):
            yield walk


def count_even_closed_walks(n_vertices: int, length: int) -> int:
    """|{even closed walks}| = E[tr(W^length)] for the +-1 ensemble."""
    return sum(1 for _ in even_closed_walks(n_vertices, length))


def expected_normalized_moment(n_vertices: int, order: int) -> float:
    """E[(1/N) tr((W/sqrt N)^order)] = #walks / N^{order/2 + 1}."""
    return count_even_closed_walks(n_vertices, order) / n_vertices ** (order / 2 + 1)


def vertices_visited(walk: Sequence[int]) -> int:
    """Number of distinct vertices; at most k+1 for an even walk of length 2k."""
    return len(set(walk))


if __name__ == "__main__":
    print(f"{'N':>3} {'m':>3} {'even walks':>12} {'max vertices':>13} {'bound k+1':>10}")
    for n in (2, 3, 4):
        for m in (3, 4, 5, 6):
            walks: List[Tuple[int, ...]] = list(even_closed_walks(n, m))
            mx = max((vertices_visited(w) for w in walks), default=0)
            bound = m // 2 + 1
            print(f"{n:>3} {m:>3} {len(walks):>12} {mx:>13} {bound:>10}")

"""Exact ensemble averaging over all sign matrices, in integer arithmetic.

Enumerates all 2^{N(N-1)/2} symmetric zero-diagonal +-1 matrices, computes
tr(W^m) exactly with integer matrix multiplication, and averages.  Used as an
independent check on the walk-counting formula E[tr(W^m)] = #{even walks}.
"""

from __future__ import annotations

from fractions import Fraction
from typing import List, Tuple


def edge_list(n: int) -> List[Tuple[int, int]]:
    return [(i, j) for i in range(n) for j in range(i + 1, n)]


def sign_matrix(n: int, mask: int) -> List[List[int]]:
    """Symmetric zero-diagonal +-1 matrix encoded by the bit pattern `mask`."""
    w = [[0] * n for _ in range(n)]
    for idx, (i, j) in enumerate(edge_list(n)):
        s = 1 if (mask >> idx) & 1 else -1
        w[i][j] = s
        w[j][i] = s
    return w


def mat_mul(a: List[List[int]], b: List[List[int]]) -> List[List[int]]:
    n = len(a)
    return [[sum(a[i][k] * b[k][j] for k in range(n)) for j in range(n)] for i in range(n)]


def mat_pow(a: List[List[int]], m: int) -> List[List[int]]:
    """Binary exponentiation: O(N^3 log m) integer operations."""
    n = len(a)
    result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    base, e = a, m
    while e:
        if e & 1:
            result = mat_mul(result, base)
        base = mat_mul(base, base)
        e >>= 1
    return result


def trace_power(a: List[List[int]], m: int) -> int:
    p = mat_pow(a, m)
    return sum(p[i][i] for i in range(len(a)))


def exact_expected_trace_power(n: int, m: int) -> Fraction:
    """E[tr(W^m)] as an exact rational number."""
    n_edges = n * (n - 1) // 2
    total = sum(trace_power(sign_matrix(n, mask), m) for mask in range(1 << n_edges))
    return Fraction(total, 1 << n_edges)


def exact_expected_normalized_moment(n: int, m: int) -> Fraction:
    """E[(1/N) tr((W/sqrt N)^m)] for even m, as an exact rational."""
    assert m % 2 == 0, "odd normalised moments involve sqrt(N); they vanish anyway"
    return exact_expected_trace_power(n, m) / Fraction(n ** (m // 2 + 1))


if __name__ == "__main__":
    print(f"{'N':>3} {'m':>3} {'E[tr W^m]':>12} {'closed form':>14}")
    for n in (2, 3, 4):
        for m in (2, 3, 4):
            val = exact_expected_trace_power(n, m)
            closed = {
                2: n * (n - 1),
                3: 0,
                4: 2 * n * (n - 1) ** 2 - n * (n - 1),
            }[m]
            print(f"{n:>3} {m:>3} {str(val):>12} {closed:>14}")

"""Monte-Carlo estimation of the spectral moments of a Wigner ensemble.

Samples R independent matrices from a chosen entry law, diagonalises each, and
averages the normalised spectral moments (1/N) sum_i (lambda_i / sqrt N)^k.
Cost: Theta(R N^3).  The estimator is used to exhibit universality: the limits
1, 0, 2, 5, ... (Catalan numbers on even orders, zero on odd orders) are
approached for every centred, unit-variance entry law.
"""

from __future__ import annotations

import math
import random
from typing import Callable, Dict, List, Sequence

import numpy as np

EntrySampler = Callable[[random.Random], float]


def rademacher(rng: random.Random) -> float:
    return 1.0 if rng.random() < 0.5 else -1.0


def gaussian(rng: random.Random) -> float:
    return rng.gauss(0.0, 1.0)


def uniform_law(rng: random.Random) -> float:
    return rng.uniform(-math.sqrt(3.0), math.sqrt(3.0))


def sparse_law(p: float = 0.1) -> EntrySampler:
    def sampler(rng: random.Random) -> float:
        if rng.random() < p:
            return (1.0 if rng.random() < 0.5 else -1.0) / math.sqrt(p)
        return 0.0

    return sampler


def sample_wigner(n: int, sampler: EntrySampler, rng: random.Random) -> np.ndarray:
    """Symmetric, zero diagonal, i.i.d. entries above the diagonal."""
    w = np.zeros((n, n), dtype=float)
    for i in range(n):
        for j in range(i + 1, n):
            w[i, j] = w[j, i] = sampler(rng)
    return w


def catalan(k: int) -> int:
    return math.comb(2 * k, k) // (k + 1)


def monte_carlo_moments(
    n: int,
    orders: Sequence[int],
    sampler: EntrySampler,
    replicates: int = 20,
    seed: int = 0,
) -> Dict[int, float]:
    """Average normalised spectral moments over `replicates` samples."""
    rng = random.Random(seed)
    acc: Dict[int, float] = {k: 0.0 for k in orders}
    for _ in range(replicates):
        w = sample_wigner(n, sampler, rng)
        lam = np.linalg.eigvalsh(w) / math.sqrt(n)
        for k in orders:
            acc[k] += float(np.mean(lam ** k))
    return {k: acc[k] / replicates for k in orders}


if __name__ == "__main__":
    orders: List[int] = [2, 3, 4, 6]
    targets = {2: 1.0, 3: 0.0, 4: 2.0, 6: 5.0}
    laws = [
        ("Rademacher", rademacher),
        ("Gaussian", gaussian),
        ("Uniform", uniform_law),
        ("Sparse 0.1", sparse_law(0.1)),
    ]
    print("target: " + "  ".join(f"m_{k}={targets[k]:.0f}" for k in orders))
    for name, law in laws:
        mom = monte_carlo_moments(300, orders, law, replicates=8, seed=7)
        print(f"{name:<12}" + "  ".join(f"{mom[k]:8.4f}" for k in orders))

