"""The Catalan reference sequence and the semicircle moment integrals.

Two independent computations of the same numbers:
  * the convolution recursion  C_{k+1} = sum_{i<=k} C_i C_{k-i},  C_0 = 1,
    which characterises the even moments of the semicircle law uniquely;
  * Simpson quadrature of (1/2pi) int_{-2}^{2} x^m sqrt(4 - x^2) dx after the
    substitution x = 2 sin t, which removes the endpoint singularity.
"""

from __future__ import annotations

import math
from typing import List


def catalan_closed_form(k: int) -> int:
    """C_k = binom(2k, k)/(k+1)."""
    return math.comb(2 * k, k) // (k + 1)


def catalan_convolution(kmax: int) -> List[int]:
    """All C_0, ..., C_kmax from the convolution recursion.  O(kmax^2)."""
    c: List[int] = [1]
    for k in range(kmax):
        c.append(sum(c[i] * c[k - i] for i in range(k + 1)))
    return c


def semicircle_moment(m: int, panels: int = 200_000) -> float:
    """(1/2pi) int_{-2}^{2} x^m sqrt(4 - x^2) dx, by Simpson in t with x = 2 sin t."""
    if panels % 2:
        panels += 1
    a, b = -math.pi / 2.0, math.pi / 2.0
    h = (b - a) / panels

    def f(t: float) -> float:
        return (2.0 * math.sin(t)) ** m * 4.0 * math.cos(t) ** 2

    total = f(a) + f(b)
    for i in range(1, panels):
        total += (4.0 if i % 2 else 2.0) * f(a + i * h)
    return (h / 3.0) * total / (2.0 * math.pi)


def wallis(m: int) -> float:
    """S_m = int_{-pi/2}^{pi/2} sin^m t dt via S_0 = pi, S_1 = 0, S_{m+2} = (m+1)/(m+2) S_m."""
    s = math.pi if m % 2 == 0 else 0.0
    for j in range(m % 2, m, 2):
        s *= (j + 1) / (j + 2)
    return s


if __name__ == "__main__":
    print(f"{'k':>3} {'convolution':>12} {'closed form':>12} {'integral':>14} {'Wallis form':>14}")
    conv = catalan_convolution(8)
    for k in range(9):
        integral = semicircle_moment(2 * k)
        wall = 2 ** (2 * k + 1) * wallis(2 * k) / ((2 * k + 2) * math.pi)
        print(f"{k:>3} {conv[k]:>12} {catalan_closed_form(k):>12} {integral:>14.6f} {wall:>14.6f}")
